//! 🗂️ Original map keys are admitted through a paged scalar hash index before typed native entries receive custody.
use super::*;
use super::super::PagedMap;
use semio_framework_value_persistent::list::PagedList;
use semio_framework_value_native_owned::native_decoding::owned::tree::{NativeSequenceReceiver,RecordEntries};
type Index=PagedList<Option<(u64,usize)>,{usize::MAX}>;
type Rows<V,const N:usize>=PagedList<(PagedUtf8<{usize::MAX}>,V),N>;
type Child<I:NativeValueSource+?Sized,V:NativeReceive<dyn NativeValueSource>+Sync,const N:usize>=NativeSequenceReceiver<I,(PagedUtf8<{usize::MAX}>,V),Rows<V,N>,RecordEntries>;
pub struct PagedMapReceiver<I:NativeValueSource+?Sized,V:NativeReceive<dyn NativeValueSource>+Sync,const N:usize>{binding:Option<RetainedCloneBinding>,index:ManuallyDrop<Option<Index>>,child:ManuallyDrop<Option<Child<I,V,N>>>,output:ManuallyDrop<Option<PagedMap<V,N>>>,retirement:RetainedCloneClose,count:usize,slots:usize,item:usize,offset:usize,probe:usize,comparison:usize,hash:u64,phase:u8,closing:bool}
impl<I:NativeValueSource+?Sized,V:NativeReceive<dyn NativeValueSource>+Sync,const N:usize> PagedMapReceiver<I,V,N>{
 fn metadata()->usize{2*size_of::<usize>()*6+size_of::<u64>()*2+size_of::<u8>()}
 fn rows(&self)->Result<&Index,ValueError>{self.index.as_ref().ok_or_else(invalid)}
 fn key<'a>(&self,input:&'a I,index:usize)->Result<&'a str,ValueError>{input.record_name(index)}
 fn paid(error:ValueError)->ValueError{let p=error.retained_progress();error.with_retained_progress(add_receipt(p,Self::metadata()).unwrap_or(p))}
}
impl<I:NativeValueSource+?Sized,V:NativeReceive<dyn NativeValueSource>+Sync,const N:usize> NativeReceive<I> for PagedMap<V,N>{
 type Receiver=PagedMapReceiver<I,V,N>;
 fn receive_birth_demand()->RetirementDemand{fixed(2*size_of::<Self::Receiver>())}
 fn begin_receive(g:RetainedCloneGrant)->Result<(Self::Receiver,RetainedCloneProgress),ValueError>{let d=<Self as NativeReceive<I>>::receive_birth_demand();if !retained_clone_grant_admits(g,d){return Err(invalid())}Ok((PagedMapReceiver{binding:None,index:ManuallyDrop::new(Some(Index::new())),child:ManuallyDrop::new(None),output:ManuallyDrop::new(None),retirement:Default::default(),count:0,slots:0,item:0,offset:0,probe:usize::MAX,comparison:0,hash:0xcbf29ce484222325,phase:0,closing:false},receipt(d)))}
}
impl<I:NativeValueSource+?Sized,V:NativeReceive<dyn NativeValueSource>+Sync,const N:usize> NativeReceiver<I,PagedMap<V,N>> for PagedMapReceiver<I,V,N>{
 fn demands(&self,input:RetainedCloneRef<'_,I>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.phase>=8{return Err(invalid())}input.check_binding(&self.binding)?;let m=Self::metadata();match self.phase{
 0=>Ok(fixed(input.binding_copy_bytes()+m)),1=>Ok(fixed(m)),
 2=>{let rows=self.rows()?;if rows.len()==self.slots{return Ok(fixed(m))}if !rows.has_reserved_slot(){nested(RetirementDemand{copy_bytes:rows.next_reserve_copy_byte_demand().map_err(|_|invalid())?,capacity_bytes:rows.next_allocation_bytes().map_err(|_|invalid())?,depth:rows.next_reserve_depth_demand().map_err(|_|invalid())?,..Default::default()},m)}else{Ok(RetirementDemand{copy_bytes:m+size_of::<Option<(u64,usize)>>(),depth:rows.next_push_depth_demand().map_err(|_|invalid())?.checked_add(1).ok_or_else(invalid)?,..Default::default()})}},
 3=>{if self.item==self.count{return Ok(fixed(m))}let key=self.key(input.get(),self.item)?;if self.probe==usize::MAX{return Ok(fixed(m+usize::from(self.offset<key.len())))}let depth=self.rows()?.next_get_depth_demand(self.probe).map_err(|_|invalid())?.checked_add(1).ok_or_else(invalid)?;Ok(RetirementDemand{copy_bytes:m+2+size_of::<Option<(u64,usize)>>(),depth,..Default::default()})},
 4=>nested(Child::<I,V,N>::birth(),2*size_of::<Option<Child<I,V,N>>>()+m),
 5=>nested(self.child.as_ref().ok_or_else(invalid)?.demands(input,body.saturating_sub(m))?,m),
 6=>nested(self.child.as_ref().ok_or_else(invalid)?.take_demand()?,2*size_of::<Rows<V,N>>()+2*size_of::<Option<PagedMap<V,N>>>()+m),
 7=>nested(self.child.as_ref().ok_or_else(invalid)?.close_demands(body.saturating_sub(m))?,m),_=>Err(invalid())}}
 fn advance(&mut self,input:RetainedCloneRef<'_,I>,control:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demands(input,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}control.checkpoint()?;let m=Self::metadata();match self.phase{
 0=>{let p=input.bind(&mut self.binding,RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-m,..g})?.ok_or_else(invalid)?;self.phase=1;return Ok(RetainedCloneStep::Progress(add_receipt(p,m)?))},
 1=>{let count=input.get().record_len()?;if count>N{return Err(invalid().with_retained_progress(receipt(d)))}self.count=count;self.slots=if count==0{0}else{count.checked_mul(2).and_then(usize::checked_next_power_of_two).ok_or_else(invalid)?};self.phase=2;},
 2=>{if self.rows()?.len()==self.slots{self.phase=3;}else{let rows=self.index.as_mut().ok_or_else(invalid)?;if !rows.has_reserved_slot(){control.charge(d.capacity_bytes)?;let p=rows.reserve_one_funded(child_grant(g,m)).map_err(|error|invalid().with_retained_progress(RetainedCloneProgress{retained_capacity_bytes:error.allocated_bytes,copied_bytes:m,copied_items:1,..Default::default()}))?;return Ok(RetainedCloneStep::Progress(add_receipt(p,m)?))}if rows.push_reserved(None).is_err(){return Err(invalid().with_retained_progress(receipt(d)))}}},
 3=>{if self.item==self.count{self.phase=4;}else{let key=self.key(input.get(),self.item)?;if self.probe==usize::MAX{if self.offset<key.len(){self.hash=(self.hash^u64::from(key.as_bytes()[self.offset])).wrapping_mul(0x100000001b3);self.offset+=1;}else{self.probe=self.hash as usize&(self.slots-1);self.comparison=0;}}else{let candidate=*self.rows()?.get(self.probe).ok_or_else(invalid)?;if let Some((hash,index))=candidate{let held=self.key(input.get(),index)?;if hash!=self.hash||held.len()!=key.len(){self.probe=(self.probe+1)&(self.slots-1);self.comparison=0;}else if self.comparison==key.len(){return Err(ValueError::literal(crate::ValueRefusalKind::InvalidValue,"native original map contains a duplicate key").with_retained_progress(receipt(d)))}else if key.as_bytes()[self.comparison]==held.as_bytes()[self.comparison]{self.comparison+=1;}else{self.probe=(self.probe+1)&(self.slots-1);self.comparison=0;}}else{let probe=self.probe;*self.index.as_mut().ok_or_else(invalid)?.get_mut(probe).ok_or_else(invalid)?=Some((self.hash,self.item));self.item+=1;self.offset=0;self.probe=usize::MAX;self.comparison=0;self.hash=0xcbf29ce484222325;}}}},
 4=>{control.charge(d.capacity_bytes)?;let extra=2*size_of::<Option<Child<I,V,N>>>()+m;let(child,p)=Child::<I,V,N>::begin(child_grant(g,extra)).map_err(Self::paid)?;*self.child=Some(child);self.phase=5;return Ok(RetainedCloneStep::Progress(add_receipt(p,extra)?))},
 5=>{let child=self.child.as_mut().ok_or_else(invalid)?;let p=child.advance(input,control,body.saturating_sub(m),child_grant(g,m)).map_err(Self::paid)?.progress();if child.output_ready(){self.phase=6}return Ok(RetainedCloneStep::Progress(add_receipt(p,m)?))},
 6=>{control.charge(d.capacity_bytes)?;let extra=2*size_of::<Rows<V,N>>()+2*size_of::<Option<PagedMap<V,N>>>()+m;let child=self.child.as_mut().ok_or_else(invalid)?;let(entries,p)=child.take(child_grant(g,extra)).map_err(Self::paid)?.ok_or_else(invalid)?;*self.output=Some(PagedMap::from_retained_entries_cloned(entries));child.begin_close();self.phase=7;return Ok(RetainedCloneStep::Progress(add_receipt(p,extra)?))},
 7=>{let child=self.child.as_mut().ok_or_else(invalid)?;let p=child.close_step(child_grant(g,m)).map_err(Self::paid)?.progress();if child.terminal_is_empty(){self.phase=8}return Ok(RetainedCloneStep::Progress(add_receipt(p,m)?))},_=>return Err(invalid())}Ok(RetainedCloneStep::Progress(receipt(d)))}
 fn output_ready(&self)->bool{!self.closing&&self.phase==8&&self.output.is_some()}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.output_ready(){return Err(invalid())}Ok(fixed(2*size_of::<Option<PagedMap<V,N>>>()+size_of::<u8>()))}
 fn take(&mut self,g:RetainedCloneGrant)->Result<Option<(PagedMap<V,N>,RetainedCloneProgress)>,ValueError>{let d=self.take_demand()?;if !retained_clone_grant_admits(g,d){return Ok(None)}self.phase=9;Ok(Some((self.output.take().ok_or_else(invalid)?,receipt(d))))}
 fn begin_close(&mut self){self.closing=true;if let Some(child)=self.child.as_mut(){child.begin_close()}}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}if let Some(child)=self.child.as_ref(){return if child.terminal_is_empty(){Ok(fixed(2*size_of::<Option<Child<I,V,N>>>()))}else{child.close_demands(body)}}if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<PagedMap<V,N>>(false,&None,body)}if self.output.is_some(){return self.retirement.next_owner_demands::<PagedMap<V,N>>(true,&None,body)}if self.index.is_some(){return self.retirement.next_owner_demands::<Index>(true,&None,body)}RetainedCloneBinding::close_demand(&self.binding,body)}
 fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demands(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if let Some(child)=self.child.as_mut(){if !child.terminal_is_empty(){return child.close_step(g)}self.child.take();return Ok(RetainedCloneStep::Progress(receipt(d)))}if !self.retirement.is_empty(){return self.retirement.step_granted(g)}if let Some(step)=self.retirement.begin_granted(&mut self.output,g)?{return Ok(step)}if let Some(step)=self.retirement.begin_granted(&mut self.index,g)?{return Ok(step)}RetainedCloneBinding::close_one(&mut self.binding,g)}
 fn terminal_is_empty(&self)->bool{self.child.is_none()&&self.output.is_none()&&self.index.is_none()&&self.retirement.is_empty()&&self.binding.is_none()}
}
impl<I:NativeValueSource+?Sized,V:NativeReceive<dyn NativeValueSource>+Sync,const N:usize> Drop for PagedMapReceiver<I,V,N>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native original map receiving requires funded closure")}}


